from openpyxl import load_workbook

wb = load_workbook('sales_data.xlsx')
ws = wb.active

header_row = None
for r in range(1, min(ws.max_row, 20) + 1):
    if any(ws.cell(row=r, column=c).value not in (None, '') for c in range(1, ws.max_column + 1)):
        header_row = r
        break
if header_row is None:
    raise SystemExit('no header row found')

headers = {}
for c in range(1, ws.max_column + 1):
    v = ws.cell(row=header_row, column=c).value
    if v is not None:
        headers[str(v).strip().lower()] = c

def find_col(*names):
    for n in names:
        for h, col in headers.items():
            if h == n:
                return col
    for n in names:
        for h, col in headers.items():
            if n in h:
                return col
    return None

profit_col = find_col('profit', 'gross profit', 'net profit', 'earnings', 'income')
rev_col = find_col('revenue', 'sales', 'gross sales', 'net sales', 'turnover', 'sales revenue', 'total revenue')
cost_col = find_col('cost', 'cogs', 'cost of goods', 'expense', 'cost of sales')

if rev_col is None:
    raise SystemExit(f'missing revenue/sales column; headers={headers}')
if profit_col is None and cost_col is None:
    raise SystemExit(f'missing profit or cost column; headers={headers}')

new_col = ws.max_column + 1
hdr = ws.cell(row=header_row, column=new_col)
hdr.value = 'Profit Margin (%)'
src_h = ws.cell(row=header_row, column=rev_col)
hdr.font = src_h.font.copy()
hdr.fill = src_h.fill.copy()
hdr.alignment = src_h.alignment.copy()
hdr.border = src_h.border.copy()
hdr.number_format = src_h.number_format

for r in range(header_row + 1, ws.max_row + 1):
    if not any(ws.cell(row=r, column=c).value not in (None, '') for c in range(1, ws.max_column + 1)):
        continue
    rev_ref = ws.cell(row=r, column=rev_col).coordinate
    if profit_col is not None:
        num_ref = ws.cell(row=r, column=profit_col).coordinate
    else:
        cost_ref = ws.cell(row=r, column=cost_col).coordinate
        num_ref = f'({rev_ref}-{cost_ref})'
    cell = ws.cell(row=r, column=new_col)
    cell.value = (f'=IF(AND(ISNUMBER({rev_ref}),{rev_ref}<>0,ISNUMBER({num_ref})),'
                  f'{num_ref}/{rev_ref},"")')
    cell.number_format = '0.0%'
    s = ws.cell(row=r, column=rev_col)
    cell.font = s.font.copy()
    cell.border = s.border.copy()
    cell.alignment = s.alignment.copy()

wb.save('sales_data.xlsx')
print(f'done: rev_col={rev_col} profit_col={profit_col} cost_col={cost_col} new_col={new_col} header_row={header_row} max_row={ws.max_row}')

